-- composition of rule kernels common_subplan x filter_pushdown (duckdb), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a4.c0 AS c0 FROM v0 AS a1, LATERAL (SELECT a3.c0 AS c0, a3.c1 AS c1 FROM v0 AS a2, (VALUES (1, 'a'::text), (2, NULL::text), (NULL::int, 'c'::text)) AS a3 (c0, c1)) AS a4) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT '2024-01-01'::date AS c0, (MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY '2000-01-01 00:00:00+00'::timestamptz) + '00:00:00.000001'::interval) AS c1 FROM t1 AS a1 WHERE NULLIF ((NULL::int < 2), FALSE)) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '2024-01-01'::date AS c0, (MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY '2000-01-01 00:00:00+00'::timestamptz) + '00:00:00.000001'::interval) AS c1 FROM t1 AS a1 WHERE NULLIF ((NULL::int < 2), FALSE)) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a4.c0 AS c0 FROM v0 AS a1, LATERAL (SELECT a3.c0 AS c0, a3.c1 AS c1 FROM v0 AS a2, (VALUES (1, 'a'::text), (2, NULL::text), (NULL::int, 'c'::text)) AS a3 (c0, c1)) AS a4) AS ka) ELSE 0 END
